def merge_intervals(intervals):
    if not intervals:
        return []
    sorted_intervals = sorted((iv[0], iv[1]) for iv in intervals)
    merged = []
    for start, end in sorted_intervals:
        if merged and start <= merged[-1][1]:
            if end > merged[-1][1]:
                merged[-1][1] = end
        else:
            merged.append([start, end])
    return merged

import heapq


def toposort(nodes, edges):
    node_set = set(nodes)
    indegree = {n: 0 for n in nodes}
    adjacency = {n: [] for n in nodes}

    for source, destination in set(edges):
        adjacency[source].append(destination)
        indegree[destination] += 1

    available = [n for n in nodes if indegree[n] == 0]
    heapq.heapify(available)

    result = []
    while available:
        current = heapq.heappop(available)
        result.append(current)
        for destination in adjacency[current]:
            indegree[destination] -= 1
            if indegree[destination] == 0:
                heapq.heappush(available, destination)

    if len(result) != len(nodes):
        raise ValueError("cycle detected")

    return result

def stable_batches(items, limit):
    if limit <= 0:
        raise ValueError("limit must be positive")
    for _, weight in items:
        if weight <= 0 or weight > limit:
            raise ValueError("invalid weight")
    batches = []
    current = []
    current_sum = 0
    for name, weight in items:
        if current and current_sum + weight > limit:
            batches.append(current)
            current = [name]
            current_sum = weight
        else:
            current.append(name)
            current_sum += weight
    if current:
        batches.append(current)
    return batches

import re

def parse_env(text):
    env = {}
    for raw_line in text.splitlines():
        line = raw_line.strip()
        if not line or line.startswith('#'):
            continue
        if '=' not in line:
            raise ValueError('invalid environment line: missing =')
        key_part, value_part = line.split('=', 1)
        key = key_part.strip()
        if not re.fullmatch(r'[A-Za-z_][A-Za-z0-9_]*', key):
            raise ValueError('invalid environment key')
        value = value_part.strip()
        if len(value) >= 2 and value[0] == value[-1] and value[0] in ("'", '"'):
            value = value[1:-1]
        env[key] = value
    return env

def parse_sse(chunks):
    text = b''.join(chunks).decode('utf-8')
    events = []
    data_lines = []
    cur = []
    i = 0
    n = len(text)

    def handle_line(line):
        if line.startswith(':'):
            return
        if ':' in line:
            field, value = line.split(':', 1)
        else:
            field, value = line, ''
        if field == 'data':
            if value.startswith(' '):
                value = value[1:]
            data_lines.append(value)

    def dispatch():
        if not data_lines:
            data_lines.clear()
            return False
        data = '\n'.join(data_lines)
        data_lines.clear()
        if data == '[DONE]':
            return True
        events.append(data)
        return False

    while i < n:
        c = text[i]
        if c == '\n' or c == '\r':
            line = ''.join(cur)
            cur = []
            if line == '':
                if dispatch():
                    return events
            else:
                handle_line(line)
            if c == '\r' and i + 1 < n and text[i + 1] == '\n':
                i += 2
            else:
                i += 1
        else:
            cur.append(c)
            i += 1

    return events

import math

def retry_delay(attempt, base, cap):
    if attempt < 0 or base < 0 or cap < 0:
        raise ValueError("arguments must be nonnegative")
    if base == 0 or cap == 0:
        return 0.0
    if attempt >= 4096:
        return float(cap)
    try:
        value = math.ldexp(float(base), attempt)
    except OverflowError:
        return float(cap)
    return float(min(float(cap), value))

def fifo_admit(active, queued, budget, slots):
    for reservation in queued:
        if reservation > budget:
            raise ValueError("queued reservation exceeds the whole budget")

    admitted = []
    remaining_budget = budget - sum(active)
    used_slots = len(active)

    for index, reservation in enumerate(queued):
        if used_slots < slots and reservation <= remaining_budget:
            admitted.append(reservation)
            remaining_budget -= reservation
            used_slots += 1
        else:
            return admitted, queued[index:]

    return admitted, []
